le":"वॉइस मेमो","explanation":"आपकी वॉइस रिकॉर्डिंग। इन्हें वॉइस मेमो ऐप से डिलीट करें।"},"books-data":{"title":"बुक्स","explanation":"डाउनलोड की गई किताबें और ऑडियोबुक। डाउनलोड बुक्स ऐप से हटाएँ।"},"notes-data":{"title":"नोट्स","explanation":"आपके नोट्स और उनके अटैचमेंट। कभी डिलीट नहीं किए जाते।"},"icloud-drive":{"title":"iCloud Drive","explanation":"iCloud Drive फ़ाइलों की लोकल कॉपी। डिलीट करने के बजाय Mac स्टोरेज ऑप्टिमाइज़ करें या 'डाउनलोड हटाएँ' इस्तेमाल करें।"},"trash":{"title":"ट्रैश","explanation":"ट्रैश में पहले से ले जाई गई फ़ाइलें, उसे खाली किए जाने तक डिस्क स्पेस घेरती रहती हैं।"},"downloads":{"title":"डाउनलोड","explanation":"हाथ से जाँचें: यहाँ के इंस्टॉलर और आर्काइव की अक्सर अब ज़रूरत नहीं होती।"},"desktop":{"title":"डेस्कटॉप","explanation":"डेस्कटॉप पर स्क्रीनशॉट और फ़ाइलें। हाथ से जाँचें।"},"documents":{"title":"दस्तावेज़","explanation":"आपके दस्तावेज़। Freeroom इस फ़ोल्डर को पूरा कभी साफ़ नहीं करता।"},"system-temp":{"title":"सिस्टम की अस्थायी फ़ाइलें","explanation":"macOS द्वारा मैनेज की जाती हैं और रीस्टार्ट पर साफ़ हो जाती हैं। हाथ से डिलीट न करें।"},"system-folder":{"title":"macOS सिस्टम","explanation":"सील किया गया, सिर्फ़-पढ़ने योग्य macOS सिस्टम वॉल्यूम। इसे न बदला जा सकता है, न बदलना चाहिए।"},"system-library":{"title":"सिस्टम लाइब्रेरी","explanation":"पूरे सिस्टम की सेटिंग्ज़, ड्राइवर और ऐप सपोर्ट। सिर्फ़ वही आइटम हटाएँ जो किसी ऐप का अनइंस्टॉलर बताए।"},"user-library":{"title":"आपका लाइब्रेरी फ़ोल्डर","explanation":"हर ऐप की सेटिंग्ज़ और डेटा। इसके अंदर के खास आइटम साफ़ करें, पूरा फ़ोल्डर कभी नहीं।"},"app-support-root":{"title":"Application Support","explanation":"हर ऐप का डेटा। सिर्फ़ खास, जाने-पहचाने सबफ़ोल्डर साफ़ करना सुरक्षित है।"},"preferences":{"title":"Preferences","explanation":"ऐप सेटिंग्ज़। इन्हें डिलीट करने से ऐप्स रीसेट हो जाते हैं।"},"keychains":{"title":"कीचेन","explanation":"आपके पासवर्ड और सर्टिफ़िकेट। कभी डिलीट नहीं किए जाते।"},"containers-root":{"title":"ऐप कंटेनर","explanation":"सैंडबॉक्स किए गए ऐप का डेटा। कंटेनर हटाने से उस ऐप का डेटा डिलीट हो जाता है।"},"group-containers-root":{"title":"ग्रुप कंटेनर","explanation":"एक ही डेवलपर के ऐप्स के बीच साझा डेटा। यह कैश नहीं है।"},"vm-swap":{"title":"स्वैप और स्लीप इमेज","explanation":"वर्चुअल मेमोरी स्वैप फ़ाइलें और स्लीप इमेज। macOS इन्हें मैनेज करता है; स्वैप घटाने के लिए रीस्टार्ट करें।"},"spotlight-index":{"title":"Spotlight इंडेक्स","explanation":"सर्च इंडेक्स। अगर यह बहुत बड़ा लगे, तो Spotlight सेटिंग्ज़ से इसे फिर से बनाएँ।"},"system-logs":{"title":"सिस्टम लॉग","explanation":"Unified logs। macOS इन्हें अपने आप रोटेट और सीमित करता है।"},"user-logs":{"title":"यूज़र लॉग","explanation":"क्रैश और हैंग रिपोर्ट जो पहले ही भेजी जा चुकी हैं या ज़रूरी नहीं हैं। नई रिपोर्ट ज़रूरत के अनुसार लिखी जाती हैं।"},"macos-updates":{"title":"macOS अपडेट डाउनलोड","explanation":"macOS द्वारा तैयार रखे गए सॉफ़्टवेयर अपडेट। इन्हें इंस्टॉल करें या macOS को हटाने दें।"},"system-caches":{"title":"सिस्टम कैश","explanation":"macOS और इंस्टॉलर द्वारा मैनेज किए जाने वाले सिस्टम-व्यापी कैश। हाथ से खाली करना सुरक्षित नहीं है।"},"time-machine-snapshots":{"title":"लोकल Time Machine स्नैपशॉट","explanation":"purgeable स्पेस के रूप में दिखते हैं। जगह की ज़रूरत होने पर macOS इन्हें अपने आप डिलीट कर देता है (`tmutil listlocalsnapshots /`)।"},"apple-intelligence-assets":{"title":"Apple सिस्टम एसेट","explanation":"डाउनलोड किए गए सिस्टम एसेट (आवाज़ें, डिक्शनरी, AI मॉडल)। macOS द्वारा मैनेज किए जाते हैं।"},"mobile-sync-config":{"title":"डिवाइस सिंक सेटिंग्ज़","explanation":"डिवाइस बैकअप और सिंक डेटा रखने वाला फ़ोल्डर। बैकअप Finder से मैनेज करें।"},"crash-reporter":{"title":"क्रैश रिपोर्टर डेटा","explanation":"macOS द्वारा रखा गया क्रैश रिपोर्ट मेटाडेटा।"},"apple-caches-misc":{"title":"Apple ऐप कैश","explanation":"App Store, सहायता, मैप्स और Safe Browsing के कैश। ज़रूरत पड़ने पर macOS इन्हें फिर से बना देता है।"},"user-caches-root":{"title":"यूज़र कैश फ़ोल्डर","explanation":"हर ऐप के कैश रखता है। इसके अंदर के जाने-पहचाने आइटम साफ़ करें, पूरा फ़ोल्डर नहीं।"},"dot-cache-root":{"title":"~/.cache फ़ोल्डर","explanation":"CLI टूल द्वारा इस्तेमाल होने वाला कैश फ़ोल्डर। इसके अंदर के जाने-पहचाने आइटम साफ़ करें, पूरा फ़ोल्डर नहीं।"},"dot-config-root":{"title":"~/.config फ़ोल्डर","explanation":"कमांड-लाइन टूल की सेटिंग्ज़। यह कैश नहीं है।"},"dot-local-root":{"title":"~/.local फ़ोल्डर","explanation":"इंस्टॉल किए गए CLI टूल और उनका डेटा। इसके अंदर के जाने-पहचाने आइटम साफ़ करें, पूरा फ़ोल्डर नहीं।"},"shell-history":{"title":"शेल हिस्ट्री","explanation":"आपकी कमांड हिस्ट्री। छोटी है; रखी जाती है।"},"git-config":{"title":"Git कॉन्फ़िग","explanation":"आपकी Git सेटिंग्ज़।"},"docker-unused-images":{"title":"इस्तेमाल न होने वाली Docker इमेज","explanation":"हर वह इमेज जिसे कोई कंटेनर इस्तेमाल नहीं करता, जानबूझकर pull की गई इमेज भी। इन्हें फिर से pull या रीबिल्ड किया जा सकता है।"},"docker-buildx-cache":{"title":"Buildx बिल्डर कैश","explanation":"buildx बिल्डर का बिल्ड कैश। कैश फिर से भरने तक एक बार बिल्ड धीमे होंगे।"},"docker-stopped-containers":{"title":"रुके हुए Docker कंटेनर","explanation":"जो कंटेनर चल नहीं रहे। हटाने पर उनकी writable लेयर और वॉल्यूम में न रखा गया सारा डेटा खो जाता है।"},"docker-unused-volumes":{"title":"इस्तेमाल न होने वाले Docker वॉल्यूम","explanation":"ऐसे वॉल्यूम जिन्हें कोई कंटेनर इस्तेमाल नहीं करता। इनमें अक्सर डेटाबेस होते हैं; `docker volume prune` से पहले जाँच लें।"},"claude-code-versions":{"title":"Claude Code वर्शन","explanation":"नेटिव Claude Code बिल्ड; मौजूदा वर्शन इस्तेमाल में है। Claude Code पुराने वर्शन खुद हटा देता है।"},"macos-aerials":{"title":"एरियल वॉलपेपर","explanation":"macOS द्वारा डाउनलोड किए गए एरियल वॉलपेपर और स्क्रीन सेवर। macOS इन्हें मैनेज करता है; डाउनलोड रोकने के लिए स्थिर वॉलपेपर चुनें।"},"xcode-userdata":{"title":"Xcode यूज़र सेटिंग्ज़","explanation":"Xcode की कीबाइंडिंग, कोड स्निपेट, थीम और ब्रेकपॉइंट।"},"command-line-tools":{"title":"Command Line Tools","explanation":"Homebrew और कई टूल द्वारा इस्तेमाल होने वाले कंपाइलर और git। रखें, जब तक पूरा Xcode इंस्टॉल और चुना हुआ न हो।"},"xcode-simulator-system-caches":{"title":"सिम्युलेटर रनटाइम कैश","explanation":"इंस्टॉल किए गए सिम्युलेटर रनटाइम के लिए बने साझा कैश। macOS इन्हें फिर से बनाता है; हटाने के लिए एडमिन अधिकार चाहिए।"},"go-bin":{"title":"Go से इंस्टॉल बाइनरी","explanation":"`go install` से इंस्टॉल किए गए टूल। जिन्हें अब इस्तेमाल नहीं करते, उन्हें हटाएँ।"},"cargo-bin":{"title":"Cargo से इंस्टॉल बाइनरी","explanation":"`cargo install` से इंस्टॉल किए गए टूल और rustup के प्रॉक्सी। `cargo uninstall <name>` से हटाएँ।"},"chrome-component-caches":{"title":"Chrome कंपोनेंट कैश","explanation":"Chrome के डाउनलोड किए गए कंपोनेंट इंस्टॉलर और GPU शेडर कैश। अपने आप फिर से बन जाते हैं; पहले Chrome बंद करें।"},"vscode-local-history":{"title":"VS Code लोकल हिस्ट्री","explanation":"VS Code में सेव की गई फ़ाइलों के पुराने वर्शन (Timeline व्यू)। इसे हटाने से वह undo हिस्ट्री खो जाती है।"},"tectonic-cache":{"title":"Tectonic TeX बंडल कैश","explanation":"Tectonic द्वारा डाउनलोड की गई TeX सपोर्ट फ़ाइलें। अगले बिल्ड पर फिर से डाउनलोड हो जाती हैं।"},"zoom-data":{"title":"Zoom चैट डेटा","explanation":"Zoom की लोकल चैट हिस्ट्री और सेटिंग्ज़। यह कैश नहीं है।"},"icloud-drive-state":{"title":"iCloud Drive स्थिति","explanation":"iCloud Drive का सिंक डेटाबेस। इसे डिलीट करने से सिंकिंग खराब हो सकती है।"},"swift-toolchains":{"title":"Swift टूलचेन","explanation":"swift.org या swiftly से लिए गए अतिरिक्त Swift टूलचेन। जिन वर्शन से अब बिल्ड नहीं करते, उन्हें हटाएँ।"},"huggingface-datasets":{"title":"Hugging Face डेटासेट कैश","explanation":"`datasets` लाइब्रेरी द्वारा डाउनलोड और प्रोसेस किए गए डेटासेट। कोड लोड करने पर फिर से डाउनलोड हो जाते हैं।"}},"id":{"xcode-derived-data":{"title":"Xcode DerivedData","explanation":"Hasil build dan indeks setiap proyek yang pernah dibuka di Xcode. Dibuat ulang pada build berikutnya."},"xcode-simulator-devices":{"title":"Perangkat simulator (app dan data)","explanation":"App dan data yang terinstal di simulator iOS. Menghapusnya mengembalikan setiap simulator ke kondisi pabrik."},"xcode-device-support":{"title":"iOS 