om-cache":{"title":"Cache Zoom","explanation":"Data cache dan file pembaruan Zoom."},"zoom-recordings":{"title":"Rekaman Zoom","explanation":"Rapat yang Anda rekam secara lokal. Pindahkan yang ingin disimpan sebelum menghapus."},"discord-cache":{"title":"Cache Discord","explanation":"Cache web app Discord. Dibuat ulang otomatis; keluar dari app terlebih dahulu."},"whatsapp-cache":{"title":"Cache WhatsApp","explanation":"Cache sementara app WhatsApp. Obrolan dan media disimpan di tempat lain."},"whatsapp-media":{"title":"Media WhatsApp","explanation":"Foto, video, dan file dari obrolan Anda. Kelola di WhatsApp > Pengaturan > Penyimpanan."},"messages-attachments":{"title":"Lampiran Pesan","explanation":"Foto dan file dari obrolan iMessage. Hapus yang besar di Pesan atau Pengaturan Sistem > Umum > Penyimpanan."},"messages-db":{"title":"Riwayat Pesan","explanation":"Database riwayat iMessage/SMS Anda. Tidak pernah dihapus."},"mail-store":{"title":"Kotak surat Mail","explanation":"Email dan kotak surat lokal Anda. Gunakan alat bawaan Mail untuk menghapus pesan."},"mail-downloads":{"title":"Unduhan Mail","explanation":"Lampiran yang Anda buka dari Mail. Aslinya tetap ada di dalam pesan."},"facetime-cache":{"title":"Data FaceTime","explanation":"Pengaturan dan data panggilan FaceTime. Kecil; disimpan."},"teams-classic-data":{"title":"Data Microsoft Teams (klasik)","explanation":"Sisa data app Teams klasik yang sudah dihentikan. Tidak dipakai oleh Teams versi baru."},"teamviewer-cache":{"title":"Cache TeamViewer","explanation":"Data cache TeamViewer."},"figma-cache":{"title":"Cache Figma desktop","explanation":"Data dan cache app Figma desktop. File tersimpan di cloud; membersihkannya membuat Anda keluar dari akun."},"spotify-cache":{"title":"Cache Spotify","explanation":"Lagu yang di-cache. Spotify mengunduhnya lagi saat dibutuhkan."},"spotify-offline":{"title":"Penyimpanan offline Spotify","explanation":"Lagu yang Anda unduh untuk didengarkan offline beserta cache Spotify