ot":{"title":"Groepscontainers","explanation":"Gegevens die gedeeld worden tussen apps van dezelfde ontwikkelaar. Geen cache."},"vm-swap":{"title":"Swap- en sluimerbestand","explanation":"Swapbestanden voor virtueel geheugen en het sluimerbestand. macOS beheert ze; herstart om swap te verkleinen."},"spotlight-index":{"title":"Spotlight-index","explanation":"Zoekindex. Bouw hem opnieuw op via de Spotlight-instellingen als hij te groot lijkt."},"system-logs":{"title":"Systeemlogs","explanation":"Unified logs. macOS roteert en beperkt ze automatisch."},"user-logs":{"title":"Gebruikerslogs","explanation":"Crash- en hangrapporten die al verstuurd of niet nodig zijn. Nieuwe worden aangemaakt wanneer nodig."},"macos-updates":{"title":"Downloads van macOS-updates","explanation":"Software-updates die macOS heeft klaargezet. Installeer ze of laat macOS ze verwijderen."},"system-caches":{"title":"Systeemcaches","explanation":"Systeembrede caches beheerd door macOS en installatieprogramma's. Niet veilig om handmatig te legen."},"time-machine-snapshots":{"title":"Lokale Time Machine-snapshots","explanation":"Getoond als vrij te maken ruimte. macOS verwijdert ze automatisch als er ruimte nodig is (`tmutil listlocalsnapshots /`)."},"apple-intelligence-assets":{"title":"Apple-systeemonderdelen","explanation":"Gedownloade systeemonderdelen (stemmen, woordenboeken, AI-modellen). Beheerd door macOS."},"mobile-sync-config":{"title":"Apparaatsynchronisatie-instellingen","explanation":"Map met reservekopieën van apparaten en synchronisatiegegevens. Beheer reservekopieën via de Finder."},"crash-reporter":{"title":"Crashrapportagegegevens","explanation":"Metagegevens van crashrapporten die macOS bewaart."},"apple-caches-misc":{"title":"Caches van Apple-apps","explanation":"Caches van App Store, Help, Kaarten en Safe Browsing. Door macOS opnieuw aangemaakt wanneer nodig."},"user-caches-root":{"title":"Map met gebruikerscaches","explanation":"Bevat de caches van alle apps. Ruim de bekende on