tion":"Pliki pomocnicze TeX pobrane przez Tectonic. Pobierane ponownie przy następnej kompilacji."},"zoom-data":{"title":"Dane czatu Zoom","explanation":"Lokalna historia czatu i ustawienia Zoom. To nie jest pamięć podręczna."},"icloud-drive-state":{"title":"Stan iCloud Drive","explanation":"Baza danych synchronizacji iCloud Drive. Jej usunięcie może zepsuć synchronizację."},"swift-toolchains":{"title":"Zestawy narzędzi Swift","explanation":"Dodatkowe zestawy narzędzi Swift ze swift.org lub swiftly. Usuń wersje, których już nie używasz."},"huggingface-datasets":{"title":"Pamięć podręczna zbiorów danych Hugging Face","explanation":"Zbiory danych pobrane i przetworzone przez bibliotekę `datasets`. Pobierane ponownie, gdy kod je wczytuje."}},"pt":{"xcode-derived-data":{"title":"Xcode DerivedData","explanation":"Produtos de compilação e índices de todos os projetos abertos no Xcode. Recriados na próxima compilação."},"xcode-simulator-devices":{"title":"Dispositivos do simulador (apps e dados)","explanation":"Apps e dados instalados nos simuladores iOS. Apagar repõe todos os simuladores no estado de fábrica."},"xcode-device-support":{"title":"iOS DeviceSupport","explanation":"Símbolos de depuração copiados de dispositivos físicos. Recriados quando um dispositivo volta a ser ligado."},"xcode-archives":{"title":"Xcode Archives","explanation":"Compilações de apps arquivadas. Necessárias para simbolizar relatórios de falhas de versões publicadas."},"xcode-caches":{"title":"Caches do Xcode","explanation":"Caches de descargas e documentação do próprio Xcode. Recriadas quando necessário."},"xcode-device-logs":{"title":"Registos de dispositivos","explanation":"Registos de falhas e diagnóstico obtidos de dispositivos ligados. Mantenha-os se ainda estiver a depurar uma falha."},"xcode-coresimulator-caches":{"title":"Caches do simulador","explanation":"Caches dyld e temporárias dos simuladores. Regeneradas quando um simulador arranca."},"xcode-xctest-devices":{"title":"Dispositivos