ông chữ dùng chung bởi các ứng dụng Office. Được tạo lại ở lần mở tiếp theo."},"microsoft-autoupdate":{"title":"Bộ nhớ đệm Microsoft AutoUpdate","explanation":"Gói cập nhật Office đã tải và đã được cài."},"cloud-storage":{"title":"Thư mục lưu trữ đám mây","explanation":"Tệp được đồng bộ bởi OneDrive, Dropbox, Google Drive và Box. Giải phóng dung lượng bằng 'Xóa bản tải về' / 'Giải phóng dung lượng' ('Remove Download' / 'Free up space')."},"adobe-media-cache":{"title":"Bộ nhớ đệm phương tiện Adobe","explanation":"Tệp âm thanh đã chuyển đổi (conformed) và tệp xem trước cho Premiere Pro và After Effects. Được tạo lại khi mở dự án."},"capcut-cache":{"title":"Bộ nhớ đệm CapCut","explanation":"Bộ nhớ đệm hiệu ứng, mẫu và bản xem trước của CapCut. Dự án được lưu ở nơi khác."},"insta360-cache":{"title":"Bộ nhớ đệm Insta360 Studio","explanation":"Bộ nhớ đệm xem trước và xuất của Insta360 Studio."},"expressvpn-cache":{"title":"Bộ nhớ đệm ExpressVPN","explanation":"Dữ liệu lưu đệm của ExpressVPN."},"sentry-crash-caches":{"title":"Bộ nhớ đệm trình báo cáo sự cố","explanation":"Báo cáo sự cố mà ứng dụng xếp hàng chờ tải lên."},"photos-library":{"title":"Thư viện Ảnh","explanation":"Ảnh và video của bạn. Bật Tối ưu hóa dung lượng máy Mac trong cài đặt Ảnh để chỉ giữ bản gốc trên iCloud."},"music-media":{"title":"Phương tiện thư viện Nhạc","explanation":"Bài hát, bản tải về và tệp đã nhập trong Nhạc. Xóa bản tải về từ ứng dụng Nhạc."},"music-cache":{"title":"Bộ nhớ đệm ứng dụng Nhạc","explanation":"Bộ nhớ đệm ảnh bìa và phát trực tuyến của ứng dụng Nhạc."},"tv-media":{"title":"Tệp tải về của ứng dụng TV","explanation":"Phim và chương trình đã tải trong ứng dụng TV. Xóa bản tải về từ ứng dụng TV."},"tv-cache":{"title":"Bộ nhớ đệm ứng dụng TV","explanation":"Bộ nhớ đệm ảnh bìa và phát trực tuyến của ứng dụng TV."},"podcasts-downloads":{"title":"Tệp tải về của Podcast","explanation":"Các tập podcast đã tải về. Xóa chúng trong Podcast > Cài đặt, hoặc bật tự động xóa."},"apple-loops":{"title":"Apple Loops và thư viện âm thanh","explanation":"Âm thanh và loop của GarageBand/Logic. Quản lý trong Logic > Sound Library thay vì xóa tệp."},"logic-library-bundle":{"title":"Thư viện Logic Pro","explanation":"Gói thư viện âm thanh của Logic Pro 12+. Xóa gói âm thanh từ Logic Pro > Sound Library."},"voice-memos":{"title":"Ghi âm","explanation":"Các bản ghi âm giọng nói của bạn. Xóa chúng từ ứng dụng Ghi âm."},"books-data":{"title":"Sách","explanation":"Sách và sách nói đã tải về. Xóa bản tải về từ ứng dụng Sách."},"notes-data":{"title":"Ghi chú","explanation":"Ghi chú và tệp đính kèm của bạn. Không bao giờ bị xóa."},"icloud-drive":{"title":"iCloud Drive","explanation":"Bản sao cục bộ của tệp iCloud Drive. Dùng Tối ưu hóa dung lượng máy Mac hoặc 'Xóa bản tải về' thay vì xóa."},"trash":{"title":"Thùng rác","explanation":"Tệp đã chuyển vào Thùng rác vẫn chiếm dung lượng ổ đĩa cho đến khi bạn dọn sạch Thùng rác."},"downloads":{"title":"Tải về","explanation":"Hãy xem xét thủ công: bộ cài đặt và tệp nén ở đây thường không còn cần nữa."},"desktop":{"title":"Màn hình nền","explanation":"Ảnh chụp màn hình và tệp trên Màn hình nền. Hãy xem xét thủ công."},"documents":{"title":"Tài liệu","explanation":"Tài liệu của bạn. Freeroom không bao giờ dọn toàn bộ thư mục này."},"system-temp":{"title":"Tệp tạm thời của hệ thống","explanation":"Do macOS quản lý và dọn khi khởi động lại. Đừng xóa thủ công."},"system-folder":{"title":"Hệ thống macOS","explanation":"Ổ đĩa hệ thống macOS được niêm phong, chỉ đọc. Không thể và không được thay đổi."},"system-library":{"title":"Thư viện hệ thống","explanation":"Cài đặt, trình điều khiển và dữ liệu hỗ trợ ứng dụng cho toàn hệ thống. Chỉ xóa mục mà trình gỡ cài đặt của ứng dụng liệt kê."},"user-library":{"title":"Thư mục Thư viện của bạn","explanation":"Cài đặt và dữ liệu của mọi ứng dụng. Dọn các mục cụ thể bên trong, không bao giờ xóa cả thư mục."},"app-support-root":{"title":"Application Support","explanation":"Dữ liệu của mọi ứng dụng. Chỉ một số thư mục con cụ thể đã biết là an toàn để dọn."},"preferences":{"title":"Preferences","explanation":"Cài đặt ứng dụng. Xóa chúng sẽ đặt lại các ứng dụng."},"keychains":{"title":"Chuỗi khóa","explanation":"Mật khẩu và chứng chỉ của bạn. Không bao giờ bị xóa."},"containers-root":{"title":"Container ứng dụng","explanation":"Dữ liệu ứng dụng chạy trong sandbox. Xóa một container sẽ xóa dữ liệu của ứng dụng đó."},"group-containers-root":{"title":"Container nhóm","explanation":"Dữ liệu dùng chung giữa các ứng dụng của cùng nhà phát triển. Không phải bộ nhớ đệm."},"vm-swap":{"title":"Swap và ảnh ngủ","explanation":"Tệp hoán đổi bộ nhớ ảo và ảnh ngủ (sleep image). macOS quản lý chúng; khởi động lại để thu nhỏ swap."},"spotlight-index":{"title":"Chỉ mục Spotlight","explanation":"Chỉ mục tìm kiếm. Tạo lại chỉ mục từ cài đặt Spotlight nếu nó có vẻ quá lớn."},"system-logs":{"title":"Nhật ký hệ thống","explanation":"Nhật ký hợp nhất. macOS tự động xoay vòng và giới hạn chúng."},"user-logs":{"title":"Nhật ký người dùng","explanation":"Báo cáo sự cố và treo máy đã được gửi hoặc không cần nữa. Báo cáo mới được ghi khi cần."},"macos-updates":{"title":"Bản cập nhật macOS đã tải","explanation":"Bản cập nhật phần mềm do macOS chuẩn bị sẵn. Hãy cài đặt hoặc để macOS tự xóa."},"system-caches":{"title":"Bộ nhớ đệm hệ thống","explanation":"Bộ nhớ đệm toàn hệ thống do macOS và trình cài đặt quản lý. Không an toàn để xóa thủ công."},"time-machine-snapshots":{"title":"Snapshot Time Machine cục bộ","explanation":"Hiển thị là dung lượng có thể xóa. macOS tự động xóa chúng khi cần dung lượng (`tmutil listlocalsnapshots /`)."},"apple-intelligence-assets":{"title":"Tài nguyên hệ thống Apple","explanation":"Tài nguyên hệ thống đã tải (giọng nói, từ điển, mô hình AI). Do macOS quản lý."},"mobile-sync-config":{"title":"Cài đặt đồng bộ thiết bị","explanation":"Thư mục chứa bản sao lưu thiết bị và dữ liệu đồng bộ. Quản lý bản sao lưu từ Finder."},"crash-reporter":{"title":"Dữ liệu trình báo cáo sự cố","explanation":"Siêu dữ liệu báo cáo sự cố do macOS lưu giữ."},"apple-caches-misc":{"title":"Bộ nhớ đệm ứng dụng Apple","explanation":"Bộ nhớ đệm của App Store, Trợ giúp, Bản đồ và Duyệt web an toàn. macOS tạo lại khi cần."},"user-caches-root":{"title":"Thư mục bộ nhớ đệm người dùng","explanation":"Chứa bộ nhớ đệm của mọi ứng dụng. Dọn các mục đã biết bên trong, không phải cả thư mục."},"dot-cache-root":{"title":"Thư mục ~/.cache","explanation":"Thư mục bộ nhớ đệm do công cụ CLI sử dụng. Dọn các mục đã biết bên trong, không phải cả thư mục."},"dot-config-root":{"title":"Thư mục ~/.config","explanation":"Cài đặt của công cụ dòng lệnh. Không phải bộ nhớ đệm."},"dot-local-root":{"title":"Thư mục ~/.local","explanation":"Công cụ CLI đã cài và dữ liệu của chúng. Dọn các mục đã biết bên trong, không phải cả thư mục."},"shell-history":{"title":"Lịch sử shell","explanation":"Lịch sử lệnh của bạn. Nhỏ; được giữ lại."},"git-config":{"title":"Cấu hình Git","explanation":"Cài đặt Git của bạn."},"docker-unused-images":{"title":"Image Docker không dùng","explanation":"Mọi image không được container nào dùng, kể cả những image bạn chủ ý pull. Có thể pull hoặc build lại."},"docker-buildx-cache":{"title":"Bộ nhớ đệm builder Buildx","explanation":"Bộ nhớ đệm build của các builder buildx. Các lần build sẽ chậm hơn một lần trong khi bộ nhớ đệm đầy lại."},"docker-stopped-containers":{"title":"Container Docker đã dừng","explanation":"Các container không chạy. Khi xóa, layer ghi được của chúng và mọi dữ liệu không nằm trong volume sẽ bị mất."},"docker-unused-volumes":{"title":"Volume Docker không dùng","explanation":"Các volume không container nào dùng. Chúng thường chứa cơ sở dữ liệu; hãy kiểm tra trước khi chạy `docker volume prune`."},"claude-code-versions":{"title":"Các phiên bản Claude Code","explanation":"Các bản build Claude Code native; bản hiện tại đang được dùng. Claude Code tự xóa phiên bản cũ."},"macos-aerials":{"title":"Hình nền Aerial","explanation":"Hình nền và trình bảo vệ màn hình Aerial mà macOS đã tải. Do macOS quản lý; chọn hình nền tĩnh để ngừng tải xuống."},"xcode-userdata":{"title":"Cài đặt người dùng Xcode","explanation":"Phím tắt, đoạn mã mẫu, chủ đề và breakpoint của Xcode."},"command-line-tools":{"title":"Command Line Tools","explanation":"Trình biên dịch và git được Homebrew và nhiều công cụ dùng. Hãy giữ lại trừ khi đã cài và chọn Xcode đầy đủ."},"xcode-simulator-system-caches":{"title":"Bộ nhớ đệm runtime Simulator","explanation":"Bộ nhớ đệm dùng chung tạo cho các runtime simulator đã cài. macOS tạo lại; cần quyền quản trị để xóa."},"go-bin":{"title":"Tệp nhị phân cài bằng Go","explanation":"Công cụ cài bằng `go install`. Xóa những cái bạn không còn dùng."},"cargo-bin":{"title":"Tệp nhị phân cài bằng Cargo","explanation":"Công cụ cài bằng `cargo install` cùng proxy của rustup. Xóa bằng `cargo uninstall <name>`."},"chrome-component-caches":{"title":"Bộ nhớ đệm thành phần Chrome","explanation":"Bộ cài thành phần đã tải và bộ nhớ đệm shader GPU của Chrome. Tự động tạo lại; hãy thoát Chrome trước."},"vscode-local-history":{"title":"Lịch sử cục bộ VS Code","explanation":"Các phiên bản trước của tệp bạn đã lưu trong VS Code (chế độ xem Timeline). Xóa đi sẽ mất lịch sử hoàn tác đó."},"tectonic-cache":{"title":"Bộ nhớ đệm gói TeX Tectonic","explanation":"Tệp hỗ trợ TeX do Tectonic tải về. Được tải lại ở lần build tiếp theo."},"zoom-data":{"title":"Dữ liệu trò chuyện Zoom","explanation":"Lịch sử trò chuyện cục bộ và cài đặt của Zoom. Không phải bộ nhớ đệm."},"icloud-drive-state":{"title":"Trạng thái iCloud Drive","explanation":"Cơ sở dữ liệu đồng bộ của iCloud Drive. Xóa nó có thể làm hỏng việc đồng bộ."},"swift-toolchains":{"title":"Toolchain Swift","explanation":"Các toolchain Swift bổ sung từ swift.org hoặc swiftly. Xóa phiên bản bạn không còn dùng để build."},"huggingface-datasets":{"title":"Bộ nhớ đệm tập dữ liệu Hugging Face","explanation":"Tập dữ liệu do thư viện `datasets` tải về và xử lý. Được tải lại khi mã nạp chúng."}},"zh-Hans":{"xcode-derived-data":{"title":"Xcode DerivedData","explanation":"Xcode 中打开过的所有项目的构建产物和索引。下次构建时会重新生成。"},"xcode-simulator-devices":{"title":"模拟器设备（App 和数据）","explanation":"iOS 模拟器中安装的 App 和数据。抹掉后所有模拟器都会恢复到出厂状态。"},"xcode-device-support":{"title":"iOS DeviceSupport","explanation":"从实体设备复制的调试符号。再次连接设备时会重新生成。"},"xcode-archives":{"title":"Xcode 归档","explanation":"已归档的 App 构建。符号化已发布版本的崩溃报告时需要用到。"},"xcode-caches":{"title":"Xcode 缓存","explanation":"Xcode 自身的下载缓存和文档缓存。需要时会重新生成。"},"xcode-device-logs":{"title":"设备日志","explanation":"从已连接设备获取的崩溃日志和诊断日志。如果你仍在调试某个崩溃，请保留它们。"},"xcode-coresimulator-caches":{"title":"模拟器缓存","explanation":"模拟器的 dyld 缓存和临时缓存。模拟器启动时会重新生成。"},"xcode-xctest-devices":{"title":"XCTest 克隆设备","explanation":"为并行测试创建的模拟器克隆。Xcode 会在下次运行测试时重新创建。"},"xcode-dvtdownloads":{"title":"Xcode 组件下载","explanation":"Xcode 为已安装的组件下载的安装包。"},"xcode-previews":{"title":"SwiftUI 预览","explanation":"用于渲染 SwiftUI 预览的模拟器数据。显示预览时会重新生成。"},"xcode-unavailable-simulators":{"title":"不可用的模拟器","explanation":"对应运行时已不再安装的模拟器。它们无法启动，因此移除不会丢失任何东西。"},"xcode-simulator-runtimes":{"title":"模拟器运行时","explanation":"iOS/watchOS/visionOS 运行时（每个数 GB）。请在 Xcode > Settings > Components 中移除不用的运行时。"},"xcode-app":{"title":"Xcode","explanation":"Xcode App 本身（10 GB 以上）。仅当你不再为 Apple 平台构建时才移除。"},"swiftpm-cache":{"title":"Swift Package Manager 缓存","explanation":"已下载的 Swift 软件包和仓库。下次解析依赖时会重新获取。"},"cocoapods-cache":{"title":"CocoaPods 缓存","explanation":"已下载的 pod。`pod install` 会重新获取。"},"cocoapods-repos":{"title":"CocoaPods spec 仓库","explanation":"CocoaPods specs 索引的本地副本。新版 CocoaPods 使用 CDN，需要时会重新创建。"},"ios-backups":{"title":"iPhone 和 iPad 备份","explanation":"由“访达”创建的本地设备备份。请在“访达”> 设备 >“管理备份”中删除旧备份。"},"docker-desktop-disk":{"title":"Docker Desktop 磁盘映像","explanation":"存放所有镜像、容器和卷的虚拟磁盘。请用 prune 命令缩小它，而不是直接删除。"},"docker-build-cache":{"title":"Docker 构建缓存","explanation":"`docker build` 缓存的层。大小取自 `docker system df`；删除后构建会变慢一次。"},"docker-dangling-images":{"title":"Docker 悬空镜像","explanation":"重新构建后遗留的无标签镜像层。没有任何容器或标签使用它们。"},"docker-desktop-caches":{"title":"Docker Desktop App 缓存","explanation":"Docker Desktop App 的日志和更新缓存，不是你的镜像或容器。"},"docker-cli-config":{"title":"Docker CLI 配置和上下文","explanation":"Docker CLI 的镜像仓库凭据和上下文。Freeroom 从不触碰它们。"},"docker-model-runner":{"title":"Docker Model Runner 模型","explanation":"用 `docker model pull` 拉取的 AI 模型。用 `docker model rm` 移除不用的模型。"},"orbstack-data":{"title":"OrbStack 数据","explanation":"包含 OrbStack 容器、镜像和 Linux 机器的磁盘映像。请在 Docker 中执行 prune，或在 OrbStack 中移除机器。"},"colima-data":{"title":"Colima 虚拟机","explanation":"Colima 的 Linux 虚拟机磁盘，包含你的镜像和容器。对不再需要的配置文件使用 `colima delete`。"},"lima-vms":{"title":"Lima 虚拟机","explanation":"Lima Linux 虚拟机的磁盘。用 `limactl delete <name>` 移除不用的虚拟机。"},"rancher-desktop":{"title":"Rancher Desktop 虚拟机","explanation":"Rancher Desktop 的虚拟机磁盘，包含镜像和 Kubernetes 状态。使用 Troubleshooting > Factory Reset 清除。"},"minikube":{"title":"minikube","explanation":"minikube 集群、虚拟机映像和缓存的 Kubernetes 二进制文件。`minikube delete --all --purge` 会移除全部内容。"},"testcontainers-config":{"title":"Testcontainers 设置","explanation":"很小的 Testcontainers 设置文件。没有可回收的空间。"},"npm-cache":{"title":"npm 缓存","explanation":"已下载的 npm 软件包。安装时会重新获取。"},"npm-npx-cache":{"title":"npx 缓存","explanation":"为运行 `npx` 命令而下载的软件包。下次运行时会重新下载。"},"npm-logs":{"title":"npm 日志","explanation":"npm 运行产生的调试日志。"},"pnpm-store":{"title":"pnpm 存储","explanation":"内容寻址的软件包存储。修剪会移除没有任何项目引用的软件包。"},"yarn-cache":{"title":"Yarn 缓存","explanation":"已下载的 Yarn 软件包。"},"yarn-berry-cache":{"title":"Yarn Berry 全局缓存","explanation":"Yarn 2+ 的全局软件包缓存。`yarn install` 会重新获取。"},"bun-cache":{"title":"Bun 安装缓存","explanation":"`bun install` 下载的软件包。需要时会重新获取。"},"deno-cache":{"title":"Deno 缓存","explanation":"Deno 的远程模块和 npm 软件包全局缓存。下次运行时会重建。"},"node-gyp-cache":{"title":"node-gyp 头文件","explanation":"为编译原生模块而下载的 Node.js 头文件。需要时会重新下载。"},"typescript-cache":{"title":"TypeScript 类型缓存","explanation":"编辑器的 TypeScript 服务器自动下载的类型定义。"},"nvm-versions":{"title":"nvm Node.js 版本","explanation":"已安装的 Node.js 版本。用 `nvm uninstall <versio